import{_ as a,W as p,s as l,u as d,I as s,ah as r,w as t,Z as o,A as i}from"./chunks/framework.Dx7wo2et.js";import"./chunks/theme.CjgFg8Ql.js";const w=JSON.parse('{"title":"如何在 Linux 中恢复一个删除了的文件 | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 中恢复一个删除了的文件 | LCTT (201611) | X-CMD","frontmatter":{"pageClass":"x-blog","head":[["meta",{"name":"og:title","content":"如何在 Linux 中恢复一个删除了的文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 中恢复一个删除了的文件 | LCTT (201611) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201611/20161109 How to Recover a Deleted File in Linux","title":"如何在 Linux 中恢复一个删除了的文件","tag":"201611"},"relativePath":"201611/20161109 How to Recover a Deleted File in Linux.md","filePath":"[post].md"}'),m={name:"201611/20161109 How to Recover a Deleted File in Linux.md"};function u(g,e,c,f,b,x){const n=p("Link");return d(),l("div",null,[e[26]||(e[26]=s("h1",{id:"如何在-linux-中恢复一个删除了的文件",tabindex:"-1"},[t("如何在 Linux 中恢复一个删除了的文件 "),s("a",{class:"header-anchor",href:"#如何在-linux-中恢复一个删除了的文件","aria-label":"Permalink to 如何在 Linux 中恢复一个删除了的文件"},"​")],-1)),e[27]||(e[27]=s("p",null,[t("你曾经是否遇到这样的事？当你发现的时候，你已经通过删除键，或者在命令行中使用 "),s("code",null,"rm"),t(" 命令，错误的删除了一个不该删除的文件。")],-1)),s("p",null,[e[1]||(e[1]=t("在第一种情况下，你可以到垃圾箱，")),o(n,{href:"http://www.tecmint.com/linux-find-command-to-search-multiple-filenames-extensions/"},{default:i(()=>e[0]||(e[0]=[t("搜索那个文件")])),_:1}),e[2]||(e[2]=t("，然后把它复原到原始位置。但是第二种情况又该怎么办呢？你可能知道，Linux 命令行不会把删除的文件转移到任何位置，而是直接把它们移除了，biu~，它们就不复存在了。"))]),e[28]||(e[28]=s("p",null,"在这篇文章里，将分享一个很有用的技巧来避免此事发生。同时，也会分享一个工具，不小心删除了某些不该删除的文件时，也许用得上。",-1)),e[29]||(e[29]=s("h3",{id:"把删除创建为-rm-i-的别名",tabindex:"-1"},[t("把删除创建为 "),s("code",null,"rm -i"),t(" 的别名 "),s("a",{class:"header-anchor",href:"#把删除创建为-rm-i-的别名","aria-label":"Permalink to 把删除创建为 `rm -i` 的别名"},"​")],-1)),s("p",null,[e[4]||(e[4]=t("当 ")),e[5]||(e[5]=s("code",null,"-i",-1)),e[6]||(e[6]=t(" 选项配合 ")),e[7]||(e[7]=s("code",null,"rm",-1)),e[8]||(e[8]=t(" 命令（也包括其他")),o(n,{href:"http://www.tecmint.com/progress-monitor-check-progress-of-linux-commands/"},{default:i(()=>e[3]||(e[3]=[t("文件处理命令比如 "),s("code",null,"cp",-1),t(" 或者 "),s("code",null,"mv",-1)])),_:1}),e[9]||(e[9]=t("）使用时，在删除文件前会出现一个提示。"))]),s("p",null,[e[11]||(e[11]=t("这同样也可以运用到当")),o(n,{href:"http://www.tecmint.com/rename-multiple-files-in-linux/"},{default:i(()=>e[10]||(e[10]=[t("复制，移动或重命名一个文件")])),_:1}),e[12]||(e[12]=t("，当所在位置已经存在一个和目标文件同名的文件时。"))]),e[30]||(e[30]=r(`<p>这个提示会给你第二次机会来考虑是否真的要删除该文件 - 如果你在这个提示上选择确定，那么文件就被删除了。这种情况下，很抱歉，这个技巧并不能防止你的粗心大意。</p><p>为了 <code>rm -i</code> 别名替代 <code>rm</code> ，这样做：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>alias rm=&#39;rm -i&#39;</span></span></code></pre></div><p>运行 <code>alias</code> 命令可以确定 <code>rm</code> 现在已经被别名了：</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/11/Add-Alias-rm-Command.png" alt="增加 rm 别名的命令"></p><p><em>为 rm 增加别名</em></p><p>然而，这只能在当前用户的当前 shell 上有效。为了永久改变，你必须像下面展示的这样把它保存到　<code>~/.bashrc</code>　中（一些版本的　Linux 系统可能是　<code>~/.profile</code>）。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2016/11/Add-Alias-Permanently-in-Linux.png" alt="在 Linux 中永久增添别名"></p><p><em>在 Linux 中永久增添别名</em></p><p>为了让 <code>~/.bashrc</code>（或 <code>~/.profile</code>）中所做的改变立即生效，从当前 shell 中运行文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>. ~/.bashrc</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/11/Active-Alias-in-Linux.png" alt="在 Linux 中激活别名"></p><p><em>在 Linux 中激活别名</em></p><h3 id="取证工具-foremost" tabindex="-1">取证工具　－　Foremost <a class="header-anchor" href="#取证工具-foremost" aria-label="Permalink to 取证工具　－　Foremost">​</a></h3><p>但愿你对于你的文件足够小心，当你要从外部磁盘或 USB 设备中恢复丢失的文件时，你只需使用这个工具即可。</p><p>然而，当你意识到你意外的删除了系统中的一个文件并感到恐慌时－不用担心。让我们来看一看 <code>foremost</code>，一个用来处理这种状况的取证工具。</p><p>要在 CentOS/RHEL 7　中安装　Foremost，需要首先启用 Repoforge：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># rpm -Uvh http://pkgs.repoforge.org/rpmforge-release/rpmforge-release-0.5.3-1.el7.rf.x86_64.rpm</span></span>
<span class="line"><span># yum install foremost</span></span></code></pre></div><p>然而在 Debian 及其衍生系统中，需这样做：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># aptitude install foremost</span></span></code></pre></div><p>安装完成后，我们做一个简单的测试吧。首先删除 <code>/boot/images</code> 目录下一个名为 <code>nosdos.jpg</code> 的图像文件：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># cd images</span></span>
<span class="line"><span># rm nosdos.jpg</span></span></code></pre></div><p>要恢复这个文件，如下所示使用 <code>foremost</code>（要先确认所在分区 - 本例中， <code>/boot</code> 位于 <code>/dev/sda1</code> 分区中）。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># foremost -t jpg -i /dev/sda1 -o /home/gacanepa/rescued</span></span></code></pre></div><p>其中，<code>/home/gacanepa/rescued</code> 是另外一个磁盘中的目录 － 请记住，把文件恢复到被删除文件所在的磁盘中不是一个明智的做法。</p><p>如果在恢复过程中，占用了被删除文件之前所在的磁盘分区，就可能无法恢复文件。另外，进行文件恢复操作前不要做任何其他操作。</p><p>当 <code>foremost</code> 执行完成以后，恢复的文件（如果可以恢复）将能够在目录 ·/home/gacanepa/rescue/jpg\` 中找到。</p><h5 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to 总结">​</a></h5><p>在这篇文章中，我们阐述了如何避免意外删除一个不该删除的文件，以及万一这类事情发生，如何恢复文件。还要警告一下， <code>foremost</code> 可能运行很长时间，时间长短取决于分区的大小。</p><p>如果您有什么问题或想法，和往常一样，不要犹豫，告诉我们。可以给我们留言。</p><hr>`,31)),s("p",null,[e[14]||(e[14]=t("via: ")),o(n,{href:"http://www.tecmint.com/recover-deleted-file-in-linux/"},{default:i(()=>e[13]||(e[13]=[t("http://www.tecmint.com/recover-deleted-file-in-linux/")])),_:1})]),s("p",null,[e[18]||(e[18]=t("作者：")),o(n,{href:"http://www.tecmint.com/author/gacanepa/"},{default:i(()=>e[15]||(e[15]=[t("Gabriel Cánepa")])),_:1}),e[19]||(e[19]=t(" 译者：")),o(n,{href:"https://github.com/ucasFL"},{default:i(()=>e[16]||(e[16]=[t("ucasFL")])),_:1}),e[20]||(e[20]=t(" 校对：")),o(n,{href:"https://github.com/jasminepeng"},{default:i(()=>e[17]||(e[17]=[t("jasminepeng")])),_:1})]),s("p",null,[e[23]||(e[23]=t("本文由 ")),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>e[21]||(e[21]=[t("LCTT")])),_:1}),e[24]||(e[24]=t(" 原创编译，")),o(n,{href:"https://linux.cn/"},{default:i(()=>e[22]||(e[22]=[t("Linux中国")])),_:1}),e[25]||(e[25]=t(" 荣誉推出"))])])}const L=a(m,[["render",u]]);export{w as __pageData,L as default};
